# Perform BFS from c4ca4238a0 to find nodes at exactly depth 3
start = 'c4ca4238a0'

# BFS tracking minimum depth to reach each node
queue = deque([(start, 0)])  # (node, depth)
visited_depth = {start: 0}
depth_nodes = {0: {start}}

while queue:
    node, depth = queue.popleft()

    if node not in adj:
        continue

    for neighbor in adj[node]:
        if neighbor not in visited_depth:
            visited_depth[neighbor] = depth + 1
            if depth + 1 not in depth_nodes:
                depth_nodes[depth + 1] = set()
            depth_nodes[depth + 1].add(neighbor)
            queue.append((neighbor, depth + 1))

print("BFS completed.")
print(f"Nodes at depth 0: {sorted(depth_nodes.get(0, set()))}")
print(f"Nodes at depth 1: {sorted(depth_nodes.get(1, set()))}")
print(f"Nodes at depth 2: {sorted(depth_nodes.get(2, set()))}")
print(f"Nodes at depth 3: {sorted(depth_nodes.get(3, set()))}")
